    let questionId = String(id ?? ''), formId = String(form ?? '');
    // Accept both lookup(questionId,formId) and lookup(formId,questionId).
    if ((packet.form_ids.includes(questionId) && !packet.form_ids.includes(formId) && own(entries,formId)) || (!own(entries,questionId) && own(entries,formId))) [questionId,formId]=[formId,questionId];
